def xorSubsetProbability(nums, target):
    basis = [0] * 31
    for x in nums:
        for b in range(30, -1, -1):
            if (x >> b) & 1:
                if basis[b]:
                    x ^= basis[b]
                else:
                    basis[b] = x
                    break
    rank = sum(1 for v in basis if v)
    t = target
    for b in range(30, -1, -1):
        if (t >> b) & 1 and basis[b]:
            t ^= basis[b]
    if t != 0:
        return "0/1"
    return f"1/{2 ** rank}"
